package com.newssignal.collector; import com.newssignal.common.Db; import org.jsoup.Jsoup; import org.jsoup.nodes.Document; import org.jsoup.nodes.Element; import org.jsoup.select.Elements; import java.net.URL; import java.sql.Connection; import java.sql.PreparedStatement; public class PopulateStocks { public static void main(String[] args) throws Exception { System.out.println("Downloading KRX list with EUC-KR..."); Document doc = Jsoup.parse(new URL("http://kind.krx.co.kr/corpgeneral/corpList.do?method=download&searchType=13").openStream(), "EUC-KR", ""); Elements rows = doc.select("tr"); System.out.println("Downloaded " + rows.size() + " rows. Inserting to DB..."); try (Connection c = Db.conn(); PreparedStatement ps = c.prepareStatement("INSERT INTO stock_master (stock_code, stock_name, market) VALUES (?, ?, 'KOSPI/KOSDAQ') ON DUPLICATE KEY UPDATE stock_name = VALUES(stock_name)")) { int count = 0; for (Element row : rows) { Elements cols = row.select("td"); if (cols.size() > 1) { String name = cols.get(0).text().trim(); String code = cols.get(1).text().trim(); if (code.matches("^[0-9]+$") && !code.isEmpty()) { if (code.length() < 6) { code = String.format("%06d", Integer.parseInt(code)); } ps.setString(1, code); ps.setString(2, name); ps.addBatch(); count++; if (count % 500 == 0) ps.executeBatch(); } } } ps.executeBatch(); System.out.println("Successfully inserted " + count + " stocks."); } } }
